"""Brute-force liveness reference for tiny graphs."""
import sys, json

def predicates(req):
    inputs = req["inputs"]
    P = len(inputs); R = len(inputs[0]) if P else 0
    D = len(inputs[0][0]) if (P and R) else 0
    states = req["states"]
    exp = []
    for q in range(R):
        acc = [0]*D
        for r in range(P):
            for i in range(D):
                acc[i] += inputs[r][q][i]
        exp.append(acc)
    safe = []; done = []
    for s in states:
        ok = True
        for r in range(P):
            for q,v in enumerate(s["delivered"][r]):
                if v != exp[q]: ok = False
        for sl in s["slots"]:
            acc = [0]*D
            for r in sl["ranks"]:
                for i in range(D):
                    acc[i] += inputs[r][sl["seq"]][i]
            if acc != sl["sum"]: ok = False
        safe.append(ok)
        done.append(all(len(s["delivered"][r]) == R for r in range(P)))
    return safe, done

def terminates_brute(req):
    states = req["states"]; edges = req["edges"]; start = req["start"]; fairness = req["fairness"]
    N = len(states)
    safe, done = predicates(req)
    if done[start]:
        return True, None
    adj = {i: [] for i in range(N)}
    for i,e in enumerate(edges):
        adj[e[0]].append((i, e[2], e[1]))
    enabled = {}
    for e in edges:
        enabled.setdefault(e[1], set()).add(e[0])
    # reachable non-done
    seen = {start}; stack=[start]
    while stack:
        v = stack.pop()
        for _,w,_ in adj[v]:
            if not done[w] and w not in seen:
                seen.add(w); stack.append(w)
    # enumerate closed walks within seen
    best = None
    maxlen = min(2*N+2, 12)
    for u in seen:
        # DFS over walks starting at u
        stack2 = [(u, [], {u}, [])]  # cur, edgeids, states, labels
        while stack2:
            cur, eids, sts, labels = stack2.pop()
            for eid, w, nm in adj[cur]:
                if w not in seen: continue
                if w == u:
                    if not eids: continue
                    # closed walk: check fairness
                    ok = True
                    for f in fairness:
                        nmf = f["action"]
                        if f["mode"] == "weak":
                            trig = all(s in enabled.get(nmf,()) for s in sts)
                        else:
                            trig = any(s in enabled.get(nmf,()) for s in sts)
                        if trig and nmf not in labels:
                            ok = False; break
                    if ok:
                        return False, (u, eids)
                else:
                    if len(eids) >= maxlen: continue
                    stack2.append((w, eids+[eid], sts | {w}, labels+[nm]))
    # stutter case
    fairnames = [f["action"] for f in fairness]
    for s in seen:
        if all(s not in enabled.get(nm,()) for nm in fairnames):
            return False, (s, "stutter")
    return True, None

if __name__ == "__main__":
    for line in open(sys.argv[1]):
        req = json.loads(line)
        if req.get("op") != "audit": continue
        t, info = terminates_brute(req)
        print(json.dumps({"terminates": t, "info": info}))
